function loadDocViewer(a, b) {
    window.location.href = '../../../Document/DocumentViewer/' + a + '/' + b;
};
function loadDocViewerExt(a, b)
{
    url = '../../../../Document/DocumentViewerExt/' + a + '/' + b;
    var width = 1000; 
    var height = 600; 
    var left = (window.innerWidth - width) / 2;
    var top = (window.innerHeight - height) / 2;
    var features = `width=${width},height=${height},left=${left},top=${top},resizable=yes,scrollbars=yes`;
    var popupWindow = window.open(url, 'CenteredWindow', features);

    if (popupWindow)
    {
        popupWindow.focus();
    }

};
function loadInvoiceViewer(a) {
    window.location.href = '../../../../Document/InvoiceViewer/'+ a;
};
function loadDocFinalizer(a) {
    window.location.href = '../../../Document/Documentfinalizer/' + a;
};
function docFinalizer(a) {
    Q.confirm("Are you sure you want to finalize this document and publish to the public repository?",
        () => {
            Q.serviceRequest(GeniusOneAi.DocumentManager.DocumentsService.baseUrl + "/Update",
                {
                    "Entity": {
                        "IsFinalized": "1"
                    },
                    "EntityId": a
                },
                (response) => { Q.alert('Document published'); location.reload(); }, { async: false });
        }, {
        onNo: () => {
            Q.notifyError("Operation cancelled!");
        },
        onCancel: () => { }
    });

};
function docClientFinalizer(a)
{
    Q.confirm("Are you sure you want to finalize this document?  This cannot be undone",
        () =>
        {
            Q.serviceRequest(GeniusOneAi.ClientManager.ClientDocumentsService.baseUrl + "/Update",
                {
                    "Entity": {
                        "IsFinalized": "1",
                },
                    "EntityId": a
                },
                (response) => { Q.alert('Document finalized'); location.reload(); }, { async: false });
        }, {
        onNo: () =>
        {
            Q.notifyError("Operation cancelled!");
        },
        onCancel: () => { }
    });

};
function docUnFinalizer(a, b)
{
    Q.confirm("Are you sure you want to unpublish this document from the public repository?",
        () => {
            Q.serviceRequest(GeniusOneAi.DocumentManager.DocumentsService.baseUrl + "/UnFinal",
                {
                    "Entity": {
                        "IsFinalized": "0",
                        "FileName":b
                    },
                    "EntityId": a
                },
                (response) => { Q.alert('Document unpublished'); location.reload(); }, { async: false });
        }, {
        onNo: () => {
            Q.notifyError("Operation cancelled!");
        },
        onCancel: () => { }
    });

};
