function payInvoice(a) {
    var dlg = new GeniusOneAi.Workflows.InvoicesDialog();
    dlg.loadByIdAndOpenDialog(a)
};
function loadPatientDocuments(a)
{
    var dlg = new GeniusOneAi.DocumentManager.DocumentSelectorDialog();
    dlg.clientID = a;
    dlg.dialogOpen(false);
};
function loadGoalLibraryDocuments(a)
{
    var dlg = new GeniusOneAi.ClientManager.ClientGoalsLibrarySelectorDialog();
    dlg.clientID = a;
    dlg.dialogOpen(false);
};
